CREATE TABLE IF NOT EXISTS broker_imports (id uuid PRIMARY KEY,broker_name text NOT NULL,zip_name text,application_id text,applicant_phone text,status text NOT NULL DEFAULT 'processing',summary jsonb NOT NULL DEFAULT '{}'::jsonb,error text,created_by text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS broker_imports_created_idx ON broker_imports(created_at DESC); CREATE INDEX IF NOT EXISTS broker_imports_application_idx ON broker_imports(application_id);
CREATE TABLE IF NOT EXISTS broker_deal_confirmations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id text NOT NULL,broker_name text NOT NULL,boreal_pct numeric(5,2),broker_pct numeric(5,2),terms text,notes text,agreed_by_broker text,agreed_on date,recorded_by text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS broker_deal_confirmations_app_uq ON broker_deal_confirmations(application_id);
